def request(folder,name,method,path,status,body=None,auth='user',mutate=False,destructive=False,source='',extra='',pre='',headers=None,external=False):
    checks=[f'pm.test("HTTP {status}", () => pm.response.to.have.status({status}));']
    guard=['function deny(message) { pm.execution.skipRequest(); throw new Error(message); }']
    if external:
        url=path
        guard+=['const u = new URL(pm.variables.replaceIn(pm.request.url.toString()));',
                'if (u.protocol !== "https:" || u.hostname !== pm.environment.get("approved_external_host")) throw new Error("Approve this external HTTPS host locally first");',
                'if (pm.request.headers.has("Authorization") || pm.request.headers.has("apikey")) throw new Error("Never forward Supabase credentials to external hosts");']
        hs=[]
    else:
        url=SB+path
        guard+=['const u = new URL(pm.variables.replaceIn(pm.request.url.toString()));',
                'const base = new URL(pm.environment.get("supabase_url"));',
                'if (pm.environment.get("target_environment") !== "staging" || u.protocol !== "https:" || u.origin !== base.origin || u.hostname !== pm.environment.get("approved_staging_host") || u.hostname.endsWith(".invalid")) throw new Error("Only the explicitly approved staging project is allowed");',
                'const key=pm.environment.get("anon_key"); if(key && key.split(".").length===3 && JSON.parse(atob(key.split(".")[1])).role!=="anon") throw new Error("JWT API key must be anon, never privileged");',
                'if (!pm.environment.get("anon_key") || pm.environment.get("anon_key").startsWith("sb_secret_")) throw new Error("Supply staging anon/publishable key locally");']
        hs=[{'key':'apikey','value':'{{anon_key}}'}]
        if auth=='user':
            hs += [{'key':'Authorization','value':'Bearer {{access_token}}'}]
            guard+=['if (!pm.variables.get("access_token") || !pm.variables.get("user_id") || pm.environment.get("synthetic_account_confirmed") !== "true") throw new Error("Use a confirmed synthetic staging account only");']
        elif auth=='legacy':
            hs += [{'key':'Authorization','value':'Bearer {{legacy_anon_jwt}}'}]
            guard+=['const t=pm.environment.get("legacy_anon_jwt"); if (!t || JSON.parse(atob(t.split(".")[1])).role !== "anon") throw new Error("Anon denial requires role=anon JWT, never service_role");']
    if mutate:
        guard += ['if (pm.environment.get("synthetic_account_confirmed") !== "true" || pm.environment.get("allow_mutations") !== "true") throw new Error("Mutations are off; explicitly enable for staging synthetic data");']
    if destructive:
        guard += ['if (pm.environment.get("allow_account_reset") !== "I_ACCEPT_SYNTHETIC_ACCOUNT_ERASURE") throw new Error("Reset/account deletion is separately disabled");']
    if pre:guard.append(pre)
    if extra:checks.append(extra)
    guard=[x.replace('throw new Error(', 'deny(') if not x.startswith('function deny') else x for x in guard]
    guard=[guard[0], 'try {', 'const URL = require("url").URL;']+guard[1:]+['} catch (e) { pm.execution.skipRequest(); throw e; }']
    if body is not None: hs += [{'key':'Content-Type','value':'application/json'}]
    if headers: hs += [{'key':k,'value':v} for k,v in headers.items()]
    req={'name':name,'request':{'method':method,'header':hs,'url':url,'auth':{'type':'noauth'},'description':source+'\nExpected status is strict, not an allowed error range. Templates never establish live deployment availability.'},'protocolProfileBehavior':{'followRedirects':False},'event':[{'listen':'prerequest','script':{'type':'text/javascript','exec':guard}},{'listen':'test','script':{'type':'text/javascript','exec':checks}}]}
    if body is not None: req['request']['body']={'mode':'raw','raw':json.dumps(body,indent=2) if not isinstance(body,str) else body,'options':{'raw':{'language':'json'}}}
    folders.setdefault(folder,[]).append(req)
    coverage.append({'request':name,'method':method,'endpoint':path,'source':source,'included':True})
    return req
